using UnityEngine;

public class Teleporter : MonoBehaviour
{
    public Transform nextStageSpawnPoint;

    private GameManager gameManager;

    void Start()
    {
        gameManager = FindFirstObjectByType<GameManager>();
        if (gameManager == null)
        {
            Debug.LogError("GameManager not found! Teleporter cannot function.");
        }
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            if (gameManager != null)
            {
                gameManager.StartNextStage(Vector3.zero);
                Destroy(gameObject);
            }
        }
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

public class Teleporter : MonoBehaviour
{
    public string nextSceneName;  // Scene to load when player enters teleporter

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            if (!string.IsNullOrEmpty(nextSceneName))
            {
                Debug.Log($"Teleporting to scene: {nextSceneName}");
                SceneManager.LoadScene(nextSceneName);
            }
            else
            {
                Debug.LogError("Teleporter has no scene name configured!");
            }
        }
    }
}
